package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.*; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="conta_bancaria") public class ContaBancariaEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(name="banco_codigo",nullable=false,length=10) public String bancoCodigo; @Column(name="banco_nome",nullable=false,length=100) public String bancoNome; @Column(length=20) public String agencia; @Column(length=30) public String conta; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="tipo_conta_bancaria") public TipoContaBancaria tipo; @Column(name="titular_nome",nullable=false,length=160) public String titularNome; @Column(name="titular_documento",length=18) public String titularDocumento; @Column(name="chave_pix",length=255) public String chavePix; @Column(nullable=false) public boolean principal; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="status_ativo") public StatusAtivo status; @Column(name="created_at",nullable=false) public Instant criadoEm; @Column(name="updated_at",nullable=false) public Instant atualizadoEm; public ContaBancariaEntity() {} }
